import sys
data = list(map(int, sys.stdin.read().split()))
if data:
    n, k = data[0], data[1]
    arr = data[2:n+2]
    seen = {}
    found = False
    for i, val in enumerate(arr):
        if val in seen and i - seen[val] <= k:
            found = True
            break
        seen[val] = i
    print('DUPLICATE' if found else 'CLEAN')
